INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2110143, 277998, 15711, '<td valign="top">I''d love to see this more like an Ann Geddes image. As it is, the baby looks kind of awkward. I''d love to see his face.</td>', 'I''d love to see this more like an Ann Geddes image. As it is, the baby looks kind of awkward. I''d love to see his face.', '2006-02-01 11:06:02.000000', NULL, 1),
(2110154, 289303, 47117, '<td valign="top">Looks like the style of Heida here at DPC. Not sure if it is, but if not, I am marking it as a favorite as I love her style of photography. The dark ominous sky in hues of blue is very attractive to me. The detail of the building is also very good. I can feel the shot, and that is nice. A 10.</td>', 'Looks like the style of Heida here at DPC. Not sure if it is, but if not, I am marking it as a favorite as I love her style of photography. The dark ominous sky in hues of blue is very attractive to me. The detail of the building is also very good. I can feel the shot, and that is nice. A 10.', '2006-02-01 11:07:34.000000', NULL, 1),
(2110158, 287778, 15711, '<td valign="top">I like the minimalist approach.  Looks like a pencil drawing. (great title)</td>', 'I like the minimalist approach.  Looks like a pencil drawing. (great title)', '2006-02-01 11:08:03.000000', NULL, 1),
(2110162, 286042, 15711, '<td valign="top">Very pretty. I''d crop above the Hooters logo on her shirt. The name tag would still be visible and I''d like that better. Great skin.</td>', 'Very pretty. I''d crop above the Hooters logo on her shirt. The name tag would still be visible and I''d like that better. Great skin.', '2006-02-01 11:08:52.000000', NULL, 1),
(2110164, 289242, 15711, '<td valign="top">Nice portrait. I''d remove the watch of the one to the right. The skin is great and the lighting = nice.  I like the post editing. 8</td>', 'Nice portrait. I''d remove the watch of the one to the right. The skin is great and the lighting = nice.  I like the post editing. 8', '2006-02-01 11:09:21.000000', NULL, 1),
(2110165, 281624, 15711, '<td valign="top">Great study in black and white. I like the light and dark. The lack of expression in the girls faces works too. Classic!</td>', 'Great study in black and white. I like the light and dark. The lack of expression in the girls faces works too. Classic!', '2006-02-01 11:10:27.000000', NULL, 1),
(2110167, 283626, 47117, '<td valign="top">Oh YES. Finally a great lightening shot. I love it! A 10!</td>', 'Oh YES. Finally a great lightening shot. I love it! A 10!', '2006-02-01 11:10:41.000000', NULL, 1),
(2110173, 279774, 47117, '<td valign="top">Darling! And love the DOF!</td>', 'Darling! And love the DOF!', '2006-02-01 11:12:48.000000', NULL, 1),
(2110180, 285344, 47117, '<td valign="top">What a cooincidence. My name is Rose too. For that, a 7! LOL...</td>', 'What a cooincidence. My name is Rose too. For that, a 7! LOL...', '2006-02-01 11:14:35.000000', NULL, 1),
(2110186, 286769, 47117, '<td valign="top">This is pretty darn cool. I love the long shot. The composition is wonderful with the sculpture.  Just nice and different. An 8.</td>', 'This is pretty darn cool. I love the long shot. The composition is wonderful with the sculpture.  Just nice and different. An 8.', '2006-02-01 11:15:47.000000', NULL, 1),
(2110189, 285065, 47117, '<td valign="top">Great action shot. Love the expression on his face too. Very nice. An 8.</td>', 'Great action shot. Love the expression on his face too. Very nice. An 8.', '2006-02-01 11:16:25.000000', NULL, 1),
