(2111480, 282280, 39144, '<td valign="top">What a lucky opportunity you had here, and great job on capturing it.</td>', 'What a lucky opportunity you had here, and great job on capturing it.', '2006-02-01 17:03:45.000000', NULL, 1),
(2111482, 285101, 43753, '<td valign="top">Interesting results with the fireworks. They look like neon feathers. I am not so sure I like the noise in the background.</td>', 'Interesting results with the fireworks. They look like neon feathers. I am not so sure I like the noise in the background.', '2006-02-01 17:04:25.000000', NULL, 1),
