(2113414, 281129, 4767, '<td valign="top">Interesting gentleman.  Interesting lighting control as well.  I like this.</td>', 'Interesting gentleman.  Interesting lighting control as well.  I like this.', '2006-02-02 01:32:00.000000', NULL, 1),
(2113421, 282156, 4767, '<td valign="top">I think this is called a "flash in the pan", and hope there was an ensuing flash out the muzzle a fraction of a second later.  Cool shot.  7</td>', 'I think this is called a "flash in the pan", and hope there was an ensuing flash out the muzzle a fraction of a second later.  Cool shot.  7', '2006-02-02 01:34:25.000000', NULL, 1),
(2113422, 284362, 43434, '<td valign="top">I think this is a lovely shot.</td>', 'I think this is a lovely shot.', '2006-02-02 01:34:29.000000', NULL, 1),
(2113423, 289211, 4767, '<td valign="top">fascinating.  Lots going on here.  Would have liked a little more detail on the right side, but  - not much light there, is there?</td>', 'fascinating.  Lots going on here.  Would have liked a little more detail on the right side, but  - not much light there, is there?', '2006-02-02 01:36:03.000000', NULL, 1),
