INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2115069, 279704, 43753, '<td valign="top">Nice grainy image. I am a little distracted though. Is the focus on the tree or the building? I do like the gritty feel though.</td>', 'Nice grainy image. I am a little distracted though. Is the focus on the tree or the building? I do like the gritty feel though.', '2006-02-02 15:17:13.000000', NULL, 1),
