(2116596, 288598, 39664, '<td valign="top">Looks like a postcard!  Very lovely and serene.</td>', 'Looks like a postcard!  Very lovely and serene.', '2006-02-02 23:52:36.000000', NULL, 1),
(2116604, 284156, 39664, '<td valign="top">I really love the crop, lighting, colors and grain in this very emotive shot.  Excellent work!  10</td>', 'I really love the crop, lighting, colors and grain in this very emotive shot.  Excellent work!  10', '2006-02-02 23:54:26.000000', NULL, 1),
