(2118471, 285525, 509, '<td valign="top">A little oversharpened (diagonal lines show this pretty clearly).  Nice colors and composition otherwise.</td>', 'A little oversharpened (diagonal lines show this pretty clearly).  Nice colors and composition otherwise.', '2006-02-03 13:38:56.000000', NULL, 1),
(2118473, 279963, 509, '<td valign="top">I think this is an interesting scene, but it is a little busy for my taste.</td>', 'I think this is an interesting scene, but it is a little busy for my taste.', '2006-02-03 13:39:50.000000', NULL, 1),
