(2119236, 288153, 24454, '<td valign="top">One of the prettiest butterfly photos I''ve ever seen.</td>', 'One of the prettiest butterfly photos I''ve ever seen.', '2006-02-03 17:16:02.000000', NULL, 1),
(2119239, 287534, 43753, '<td valign="top">Very cool drops. I think the colors look great.</td>', 'Very cool drops. I think the colors look great.', '2006-02-03 17:16:43.000000', NULL, 1),
