(2119266, 280772, 43753, '<td valign="top">Creative composition!!</td>', 'Creative composition!!', '2006-02-03 17:24:29.000000', NULL, 1),
(2119269, 287922, 24454, '<td valign="top">This is beautiful.  The lighting is perfect.</td>', 'This is beautiful.  The lighting is perfect.', '2006-02-03 17:25:23.000000', NULL, 1),
(2119271, 289410, 24454, '<td valign="top">Wow!   I love the composition on this one.  It''s striking and jumps out at you.  I can realy see this matted and framed hanging in a sunny yellow kitchen.  Great job.</td>', 'Wow!   I love the composition on this one.  It''s striking and jumps out at you.  I can realy see this matted and framed hanging in a sunny yellow kitchen.  Great job.', '2006-02-03 17:26:15.000000', NULL, 1),
