(2126690, 289221, 37961, '<td valign="top">Really good photo. The bubbles and the focus are right on. Nice! 10.</td>', 'Really good photo. The bubbles and the focus are right on. Nice! 10.', '2006-02-06 11:29:10.000000', NULL, 1),
(2126692, 285757, 37961, '<td valign="top">Love the light and colors. Really interesting photo. Great color saturation and clarity. 10.</td>', 'Love the light and colors. Really interesting photo. Great color saturation and clarity. 10.', '2006-02-06 11:29:35.000000', NULL, 1),
