INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2127048, 282032, 50982, '<td valign="top">Like the concept, seems rather over processed. More like a jpg that has been edited and saved a few too many times.</td>', 'Like the concept, seems rather over processed. More like a jpg that has been edited and saved a few too many times.', '2006-02-06 14:32:14.000000', NULL, 1),
