INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2130287, 287636, 50231, '<td valign="top">The head feathers seem way blown out and to me that stick/branch going from the the Eagle to the right side of the image is distracting.</td>', 'The head feathers seem way blown out and to me that stick/branch going from the the Eagle to the right side of the image is distracting.', '2006-02-07 16:29:36.000000', NULL, 1),
